var catalog=LevelCatalog.Load(catalogRoot);var lib=new UniversalSourceLibrary(originalBin,catalog);var host=lib.Get("artisans");var src=lib.Get("magiccrafters");output=Path.GetFullPath(output);if(Directory.Exists(output)||File.Exists(output))throw new IOException("Preserve ordinary export");Directory.CreateDirectory(output);File.Copy(Path.Combine(catalogRoot,"spyro-level-catalog.json"),Path.Combine(output,"spyro-level-catalog.json"),false);int checks=0;void Check(bool x,string why){checks++;if(!x)throw new InvalidDataException(why);}void Refuse(Action f,string why){try{f();}catch(InvalidDataException){checks++;return;}throw new Exception("Unrefused:"+why);}string H(byte[] b)=>Convert.ToHexStringLower(SHA256.HashData(b));
