var root=new UniversalMobyPlacement("magiccrafters",12,84742,51354,9568,EditorId:Guid.NewGuid().ToString("N"),PersistentSlot:0);var pair=UniversalPlacementGroups.Expand(lib.Get,root);foreach(var p in pair){var m=Decode(src.Data.Row(p.SourceRowIndex),mobys.Count);m.IsAdded=true;m.Position=new(p.X/16f,p.Y/16f,p.Z/16f);m.UniversalPlacementId=p.EditorId!;m.UniversalLinkGroupId=p.LinkGroupId!;m.CrossLevelTemplateId="universal:magiccrafters:"+p.SourceRowIndex;m.CrossLevelFamily="universal";m.CrossLevelSourceLevelKey="magiccrafters";m.CrossLevelSourceLevelName="Magic Crafters";m.CrossLevelSourceTrueIndex=p.SourceRowIndex;m.CrossLevelRequiredExporterFeature=UniversalMobyExport.RequiredExporterFeature;mobys.Add(m);}
