foreach(int row in removed)foreach(int axis in new[]{12,16,20}){var b=staged.EntryBytes(10);var sc=new UniversalLevelData(b).Scene();b[new UniversalLevelData(b).Subfiles()[3].Offset+sc.RowsOffset+row*88+axis]^=1;Refuse(()=>UniversalMagicArtisansHost.RestoreSavedDeletions(b,staged.EntryBytes(9),staged.Exe,removed),"every owned staged coordinate mutation");}
